baseline_output_query:
PREFIX cmt: <http://cmt#> 

SELECT distinct ?s ?o WHERE {
?s cmt:name ?o .
}

PREFIX cmt: <http://cmt#> 

SELECT distinct ?s ?o WHERE {
?s cmt:name ?o .
}

input_query:
PREFIX cmt: <http://cmt#>
SELECT ?conference ?name
WHERE {
	?conference a cmt:Conference ;
		cmt:name ?name .
}

custom_output_query:
PREFIX  cmt:  <http://cmt#>

SELECT  ?conference ?name
WHERE
  { ?conference  a                  <http://conference#Conference> ;
              <http://conference#has_a_name>  ?name ;
              a                     cmt:Conference
  }

custom_final_query:
PREFIX  cmt:  <http://cmt#>
SELECT  ?conference ?name
WHERE {
  ?conference a <http://conference#Conference> .
  ?conference <http://conference#has_a_name> ?name .
  OPTIONAL { ?conference a cmt:Conference . }
}

