WHERE {
  ?reviewer rdf:type <http://conference#Reviewer> .
  OPTIONAL { ?reviewer cmt:hasBeenAssigned ?paper . }
}

input_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX cmt: <http://cmt#>

SELECT ?conference ?name ?date ?reviewsPerPaper
WHERE {
  ?conference rdf:type cmt:Conference .
  ?conference cmt:name ?name ;
              cmt:date ?date ;
              cmt:reviewsPerPaper ?reviewsPerPaper .
}

custom_output_query:
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  cmt:  <http://cmt#>

SELECT  ?conference ?name ?date ?reviewsPerPaper
WHERE
  { ?conference  rdf:type           <http://conference#Conference> ;
              <http://conference#has_a_name>  ?name ;
              rdf:type              cmt:Conference ;
              cmt:date              ?date ;
              cmt:reviewsPerPaper   ?reviewsPerPaper
  }

custom_final_query:
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  cmt:  <http://cmt#>

SELECT  ?conference ?name ?date ?reviewsPerPaper
WHERE
  { ?conference  rdf:type           <http://conference#Conference> ;
              <http://conference#has_a_name>  ?name ;
              rdf:type              cmt:Conference ;
              cmt:date              ?date ;
              cmt:reviewsPerPaper   ?reviewsPerPaper
  }

